247  static int
   248  write_blob( Write *write, const char *field, int app )
   249  {
   250          unsigned char *data;
   251          size_t data_length;
   252
   253          if( vips_image_get_typeof( write->in, field ) ) {
   254                  if( vips_image_get_blob( write->in, field,
   255                          (void *) &data, &data_length ) )
   256                          return( -1 );
   257
   258                  /* Single jpeg markers can only hold 64kb, large objects must
   259                   * be split into multiple markers.
   260                   *
   261                   * Unfortunately, how this splitting is done depends on the
   262                   * data type. For example, ICC and XMP have completely
   263                   * different ways of doing this.
   264                   *
   265                   * For now, just ignore oversize objects and warn.
   266                   */
   267                  if( data_length > 65530 )
   268                          g_warning( _( "field \"%s\" is too large "
   269                                  "for a single JPEG marker, ignoring" ),
   270                                  field );
   271                  else {
   272  #ifdef DEBUG
   273                          printf( "write_blob: attaching %zd bytes of %s\n",
   274                                  data_length, field );
   275  #endif /*DEBUG*/
   276
   277                          jpeg_write_marker( &write->cinfo, app,
   278                                  data, data_length );
   279                  }
   280          }
   281
   282          return( 0 );
   283  }
