   287  static int
   288  write_xmp( Write *write )
   289  {
   290          unsigned char *data;
   291          size_t data_length;
   292          char *p;
   293
   294          if( !vips_image_get_typeof( write->in, VIPS_META_XMP_NAME ) )
   295                  return( 0 );
   296          if( vips_image_get_blob( write->in, VIPS_META_XMP_NAME,
   297                  (void *) &data, &data_length ) )
   298                  return( -1 );
   299
   300          /* To write >64kb XMP it you need to parse the whole XMP object,
   301           * pull out the most important fields, code just them into the main
   302           * XMP block, then write any remaining XMP objects into a set of
   303           * extended XMP markers.
   304           *
   305           * http://wwwimages.adobe.com/content/dam/Adobe/en/devnet/xmp/pdfs/ \
   306           *      XMPSpecificationPart3.pdf
   307           *
   308           * jpeg_write_marker() with some libjpeg versions will throw a fatal
   309           * error with large chunks.
   310           */
   311          if( data_length > 60000 ) {
   312                  g_warning( "%s", _( "VipsJpeg: large XMP not saved" ) );
   313                  return( 0 );
   314          }
   315
   316          /* We need to add the magic XML URL to the start, then a null
   317           * character, then the data.
   318           */
   319          p = g_malloc( data_length + strlen( XML_URL ) + 1 );
   320          strcpy( p, XML_URL );
   321          memcpy( p + strlen( XML_URL ) + 1, data, data_length );
   322
   323          jpeg_write_marker( &write->cinfo, JPEG_APP0 + 1,
   324                  (unsigned char *) p, data_length + strlen( XML_URL ) + 1 );
   325
   326          g_free( p );
   327
   328          return( 0 );
   329  }
