   340  /* ICC writer from lcms, slight tweaks.
   341   */
   342
   343  #define ICC_MARKER  (JPEG_APP0 + 2)     /* JPEG marker code for ICC */
   344  #define ICC_OVERHEAD_LEN  14            /* size of non-profile data in APP2 */
   345  #define MAX_BYTES_IN_MARKER  65533      /* maximum data len of a JPEG marker */
   346  #define MAX_DATA_BYTES_IN_MARKER  (MAX_BYTES_IN_MARKER - ICC_OVERHEAD_LEN)
   347
   348  /*
   349   * This routine writes the given ICC profile data into a JPEG file.
   350   * It *must* be called AFTER calling jpeg_start_compress() and BEFORE
   351   * the first call to jpeg_write_scanlines().
   352   * (This ordering ensures that the APP2 marker(s) will appear after the
   353   * SOI and JFIF or Adobe markers, but before all else.)
   354   */
   355
   356  static void
   357  write_profile_data (j_compress_ptr cinfo,
   358                     const JOCTET *icc_data_ptr,
   359                     unsigned int icc_data_len)
   360  {
   361    unsigned int num_markers;     /* total number of markers we'll write */
   362    int cur_marker = 1;           /* per spec, counting starts at 1 */
   363    unsigned int length;          /* number of bytes to write in this marker */
   364
   365    /* rounding up will fail for length == 0 */
   366    g_assert( icc_data_len > 0 );
   367
   368    /* Calculate the number of markers we'll need, rounding up of course */
   369    num_markers = (icc_data_len + MAX_DATA_BYTES_IN_MARKER - 1) /
   370            MAX_DATA_BYTES_IN_MARKER;
   371
   372    while (icc_data_len > 0) {
   373      /* length of profile to put in this marker */
   374      length = icc_data_len;
   375      if (length > MAX_DATA_BYTES_IN_MARKER)
   376        length = MAX_DATA_BYTES_IN_MARKER;
   377      icc_data_len -= length;
   378
   379      /* Write the JPEG marker header (APP2 code and marker length) */
   380      jpeg_write_m_header(cinfo, ICC_MARKER,
   381                          (unsigned int) (length + ICC_OVERHEAD_LEN));
   382
   383      /* Write the marker identifying string "ICC_PROFILE" (null-terminated).
   384       * We code it in this less-than-transparent way so that the code works
   385       * even if the local character set is not ASCII.
   386       */
   387      jpeg_write_m_byte(cinfo, 0x49);
   388      jpeg_write_m_byte(cinfo, 0x43);
   389      jpeg_write_m_byte(cinfo, 0x43);
   390      jpeg_write_m_byte(cinfo, 0x5F);
   391      jpeg_write_m_byte(cinfo, 0x50);
   392      jpeg_write_m_byte(cinfo, 0x52);
   393      jpeg_write_m_byte(cinfo, 0x4F);
   394      jpeg_write_m_byte(cinfo, 0x46);
   395      jpeg_write_m_byte(cinfo, 0x49);
   396      jpeg_write_m_byte(cinfo, 0x4C);
   397      jpeg_write_m_byte(cinfo, 0x45);
   398      jpeg_write_m_byte(cinfo, 0x0);
   399
   400      /* Add the sequencing info */
   401      jpeg_write_m_byte(cinfo, cur_marker);
   402      jpeg_write_m_byte(cinfo, (int) num_markers);
   403
   404      /* Add the profile data */
   405      while (length--) {
   406        jpeg_write_m_byte(cinfo, *icc_data_ptr);
   407        icc_data_ptr++;
   408      }
   409      cur_marker++;
   410    }
   411  }
